# Code generated by Claude
"""The navigation grid: one projected obstacle layer from the world model's blocking entries, the robot's footprint bands and Nav2-style inflation costs
(overnight queue stage 2; navigation proposal sections 4 and 5 (N1 to N4); decisions-log M053, M054; Nav2 names where they exist: `resolution`, `inflation_radius`, `cost_scaling_factor`).

    grid = NavGrid(footprint, cfg=NAV_CFG, bounds=(-6, 6, -6, 6))
    grid.rebuild(obstacles)                       # obstacles: entries with .outline (N, 2) and .height_range (z_low, z_high) (src/world_model.Entry), or the same as dicts
    grid.blocked_for(k)                           # bool (ny, nx): the robot origin cells where the footprint, turned to the direction of travel k (0 to 7, k * 45 degrees), hits something
    grid.cost                                     # uint8 (ny, nx): Nav2's inflation cost: 254 lethal (inside an obstacle), 253 inscribed (the origin within the inscribed radius), else 252 * exp(-factor * (d - r_in))

Rules (all settings in NAV_CFG):
  * An entry blocks the floor when it has an outline and a height range that overlaps the robot's height band (0, h_top) and reaches up at least `min_block_height` above the floor (an obstacle
    lower than 1 cm does not block: Nav2's `min_obstacle_height`; M054). The open bench therefore blocks its whole outline: A* never drives under an overhang (N2).
  * A cell is blocked when the obstacle lies closer than the inscribed radius r_in to the cell centre, free when farther than the circumscribed radius r_out; in between, only when the real footprint at
    the direction of travel overlaps an obstacle (the footprint turned to that direction, dilated over the obstacle mask: the obstacle mask grown by the footprint reflected through the origin).
  * `version` increases only when the set of blocking outlines really changes, so a source that rewrites the same values every tick does not trigger a replan (N3). The fixtures' part is kept
    (cached) and only the other entries are repainted.
  * Everything outside the grid is blocked.

The grid is never a source of truth: it is rebuilt from the world model's obstacles.

Contents:
    footprint_radii, rasterize_polygon, NavGrid.
"""

import math

import cv2
import numpy as np
from scipy import ndimage

from src.task_config import NAV_CFG


def footprint_radii(poly):
    """The inscribed and the circumscribed radius of a footprint polygon about the base origin.

    Args:
        poly (array-like): (K, 2) vertices in the base frame (x forward, y left), metres, convex, the origin inside.

    Returns:
        tuple: (r_in, r_out): the smallest distance from the origin to an edge, the largest distance to a vertex, metres.
    """
    P = np.asarray(poly, float)
    r_out = float(np.hypot(P[:, 0], P[:, 1]).max())
    best = float("inf")
    for a, b in zip(P, np.roll(P, -1, axis=0)):
        e = b - a
        n = float(np.hypot(*e))
        best = min(best, abs(a[0] * e[1] - a[1] * e[0]) / n if n > 0 else float("inf"))
    return best, r_out


def rasterize_polygon(poly, origin, res, shape):
    """Fills a polygon (world xy) on a grid: cell (iy, ix) covers x from origin[0] + ix * res and y from origin[1] + iy * res (the image convention: rows are y).

    Args:
        poly (array-like): (N, 2) vertices, metres.
        origin (array-like): World (x, y) of the grid's corner.
        res (float): Cell edge, metres.
        shape (tuple): (ny, nx).

    Returns:
        numpy.ndarray: Bool (ny, nx), True for the cells the polygon covers (cells touched by its boundary included).
    """
    img = np.zeros(shape, np.uint8)
    pts = np.round((np.asarray(poly, float) - np.asarray(origin, float)) / res * 16).astype(np.int32)
    cv2.fillPoly(img, [pts.reshape(-1, 1, 2)], 1, lineType=cv2.LINE_8, shift=4)
    cv2.polylines(img, [pts.reshape(-1, 1, 2)], True, 1, thickness=1, lineType=cv2.LINE_8, shift=4)
    return img.astype(bool)


def _get(entry, name):
    return entry.get(name) if isinstance(entry, dict) else getattr(entry, name, None)


class NavGrid:
    """The 2D planning grid (see the module docstring).

    Attributes:
        res (float): Cell edge, metres (NAV_CFG["cell"], Nav2's resolution).
        origin (numpy.ndarray): World (x, y) of cell (0, 0)'s corner.
        shape (tuple): (ny, nx).
        footprint (numpy.ndarray): The footprint polygon in the base frame.
        r_in, r_out (float): Its inscribed and circumscribed radii.
        h_top (float): The robot's height at the drive configuration; entries below it (and above the floor by min_block_height) block.
        version (int): Increases when the blocking outlines change.
        mask (numpy.ndarray): Bool (ny, nx): cells touched by a blocking obstacle.
        dist (numpy.ndarray): Float (ny, nx): the distance from each cell centre to the nearest obstacle cell edge, metres (large where there is none).
        cost (numpy.ndarray): uint8 (ny, nx): Nav2's inflation cost (see the module docstring).
    """

    LETHAL, INSCRIBED = 254, 253

    def __init__(self, footprint, cfg=NAV_CFG, bounds=(-6.0, 6.0, -6.0, 6.0), h_top=1.1):
        """Sets up an empty grid.

        Args:
            footprint (array-like): (K, 2) the robot's outline from above in the base frame, metres (src/nav_footprint.robot_footprint).
            cfg (dict): NAV_CFG. Defaults to it.
            bounds (tuple): x min, x max, y min, y max of the grid, metres. Defaults to the room's inside (+-6 m).
            h_top (float): The robot's height at the drive configuration (arms at the zombie pose), metres. Defaults to 1.1.
        """
        self.cfg, self.res = cfg, float(cfg["cell"])
        self.origin = np.array([bounds[0], bounds[2]], float)
        self.shape = (int(round((bounds[3] - bounds[2]) / self.res)), int(round((bounds[1] - bounds[0]) / self.res)))
        self.footprint = np.asarray(footprint, float)
        self.r_in, self.r_out = footprint_radii(self.footprint)
        self.h_top = float(h_top)
        self.version = 0
        self._sig = None
        self._fixed_sig, self._fixed_mask = None, None
        self.mask = np.zeros(self.shape, bool)
        self._update_fields()
        self._kernels = {}

    # ------------------------------------------------------------------ building
    def blocks_floor(self, e):
        """Whether a world-model entry blocks the floor for the robot (see the module docstring)."""
        outline, hr = _get(e, "outline"), _get(e, "height_range")
        if outline is None or hr is None or _get(e, "blocks_floor") is False:
            return False
        z0, z1 = hr
        return bool(z1 >= self.cfg["min_block_height"] and z0 <= self.h_top)

    def _paint(self, entries):
        m = np.zeros(self.shape, bool)
        for e in entries:
            m |= rasterize_polygon(np.asarray(_get(e, "outline"), float), self.origin, self.res, self.shape)
        return m

    def rebuild(self, obstacles):
        """Repaints the grid from the world model's obstacle entries. The fixtures' part (found = "map") is kept between calls while it is unchanged.

        Args:
            obstacles (iterable): Entries (or dicts) with outline, height_range and found.

        Returns:
            bool: True if the blocking outlines changed (the version increased).
        """
        blocking = [e for e in obstacles if self.blocks_floor(e)]
        fixed = [e for e in blocking if _get(e, "found") == "map"]
        other = [e for e in blocking if _get(e, "found") != "map"]
        sig = lambda es: tuple(sorted((str(_get(e, "id")), tuple(np.round(np.asarray(_get(e, "outline"), float), 4).ravel().tolist()), tuple(np.round(_get(e, "height_range"), 4))) for e in es))
        fsig, osig = sig(fixed), sig(other)
        if (fsig, osig) == self._sig:
            return False
        if fsig != self._fixed_sig:
            self._fixed_mask, self._fixed_sig = self._paint(fixed), fsig
        self.mask = self._fixed_mask | self._paint(other)
        self._sig = (fsig, osig)
        self.version += 1
        self._update_fields()
        self._kernels_blocked = {}
        return True

    def _update_fields(self):
        """The distance to the nearest obstacle cell, the inflation cost and the hard walls of the grid."""
        cfg, res = self.cfg, self.res
        if self.mask.any():
            d = ndimage.distance_transform_edt(~self.mask) * res
            d = np.maximum(d - 0.5 * res, 0.0)                         # cell centre to the obstacle cell's edge
        else:
            d = np.full(self.shape, 1e3)
        self.dist = d
        cost = np.zeros(self.shape, float)
        infl = d <= cfg["inflation_radius_extra"] + self.r_in
        cost[infl] = 252.0 * np.exp(-cfg["cost_scaling_factor"] * np.maximum(d[infl] - self.r_in, 0.0))
        cost[d <= self.r_in] = self.INSCRIBED
        cost[self.mask] = self.LETHAL
        self.cost = np.clip(cost, 0, 254).astype(np.uint8)
        self._blocked = {}

    # ------------------------------------------------------------------ queries
    def kernel(self, heading):
        """The footprint at a heading rasterized on the grid, as a kernel centred on the origin cell."""
        key = round(math.degrees(heading) % 360.0, 3)
        if key not in self._kernels:
            c, s = math.cos(heading), math.sin(heading)
            P = self.footprint @ np.array([[c, s], [-s, c]])           # rotate by the heading (rows are points)
            half = int(math.ceil(self.r_out / self.res)) + 1
            n = 2 * half + 1
            K = rasterize_polygon(P, np.array([-half * self.res - 0.5 * self.res, -half * self.res - 0.5 * self.res]), self.res, (n, n))
            self._kernels[key] = K.astype(np.uint8)
        return self._kernels[key]

    def blocked_for(self, k):
        """The robot origin cells blocked for travel in direction k (0 to 7, k * 45 degrees): the obstacle mask grown by the footprint at that heading (a cell is blocked when the footprint there
        overlaps an obstacle cell), the cells within the inscribed radius of an obstacle, the lethal cells and the grid's border."""
        if k not in self._blocked:
            K = self.kernel(k * math.pi / 4)[::-1, ::-1]               # reflected: the origin cells from which the footprint reaches an obstacle
            grown = cv2.dilate(self.mask.astype(np.uint8), K, borderType=cv2.BORDER_CONSTANT, borderValue=0).astype(bool)
            b = grown | (self.dist <= self.r_in) | self.mask
            b[0, :] = b[-1, :] = b[:, 0] = b[:, -1] = True
            self._blocked[k] = b
        return self._blocked[k]

    def blocked_at_heading(self, xy, heading):
        """Whether the footprint at a world position and an exact heading overlaps an obstacle cell (the grid's own resolution; the exact test is nav_smooth.verify)."""
        ix, iy = self.cell_of(xy)
        if not (0 <= ix < self.shape[1] and 0 <= iy < self.shape[0]):
            return True
        K = self.kernel(heading)
        half = K.shape[0] // 2
        y0, y1, x0, x1 = iy - half, iy + half + 1, ix - half, ix + half + 1
        if y0 < 0 or x0 < 0 or y1 > self.shape[0] or x1 > self.shape[1]:
            return True
        return bool((self.mask[y0:y1, x0:x1] & K.astype(bool)).any())

    def cell_of(self, xy):
        """The (ix, iy) of a world position."""
        return int(math.floor((xy[0] - self.origin[0]) / self.res)), int(math.floor((xy[1] - self.origin[1]) / self.res))

    def centre_of(self, ix, iy):
        """The world position of a cell's centre."""
        return np.array([self.origin[0] + (ix + 0.5) * self.res, self.origin[1] + (iy + 0.5) * self.res])

    def turn_clear(self, xy, grow=0.0):
        """Whether a full in-place turn at a world position is clear: the disc of radius r_out (+ grow) must not touch any obstacle (N7: the full swept circle)."""
        ix, iy = self.cell_of(xy)
        if not (0 <= ix < self.shape[1] and 0 <= iy < self.shape[0]):
            return False
        return bool(self.dist[iy, ix] > self.r_out + grow)
